.pon-table {
  width: 150px;

  font-family: Arial, sans-serif;

  background: #11181d;

  border-radius: 4px;

  overflow: hidden;
  margin-bottom: 15px;
  
  
  
  
}

.pon-header {
  height: 50px;

  display: flex;
  align-items: center;

  padding: 0 10px;

  background: #161d22;

  color: #d9e0e4;

  font-size: 11px;
  font-weight: 700;

  border-bottom: 1px solid #263138;
}

.pon-row {
  height: 28px;

  display: flex;
  align-items: center;

  padding: 20px 10px;
 

  box-sizing: border-box;

  color: #d8dee2;

  font-size: 15px;
  font-weight: 600;

  background: #10171b;

  border-bottom: 1px solid #1c272d;

  white-space: nowrap;
}

.pon-row:hover {
  background: #182229;
}

/* ============================= */
/* HEADER DA OLT */
/* ============================= */

.olt-header {
  width: 100%;
  min-height: 72px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 10px 16px;
  margin-bottom: 8px;

  box-sizing: border-box;

  background:
    linear-gradient(
      110deg,
      rgba(15, 22, 27, 0.98),
      rgba(10, 14, 18, 0.98)
    );

  border: 1px solid rgba(32, 223, 134, 0.18);
  border-left: 4px solid #20df86;

  border-radius: 9px;

  box-shadow:
    0 0 15px rgba(32, 223, 134, 0.08),
    inset 0 0 15px rgba(255, 255, 255, 0.015);
}


/* ============================= */
/* HEADER - LADO ESQUERDO */
/* ============================= */

.olt-header-left {
  display: flex;
  align-items: center;

  gap: 12px;

  min-width: 0;
}


.olt-icon {
  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  border: 2px solid #20df86;

  color: #20df86;

  font-size: 11px;
  font-weight: 700;

  box-shadow:
    0 0 10px rgba(32, 223, 134, 0.30);
}


.olt-identification {
  display: flex;
  flex-direction: column;

  min-width: 0;
}


.olt-name {
  color: #ffffff;

  font-size: 17px;
  font-weight: 700;

  letter-spacing: 0.4px;

  white-space: nowrap;
}


.olt-description {
  margin-top: 3px;

  color: #7f8b93;

  font-size: 10px;
  font-weight: 500;

  white-space: nowrap;
}


/* ============================= */
/* HEADER - LADO DIREITO */
/* ============================= */

.olt-header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;

  gap: 5px;

  flex-shrink: 0;
}


.olt-status {
  display: flex;
  align-items: center;

  gap: 7px;

  color: #20df86;

  font-size: 11px;
  font-weight: 700;

  white-space: nowrap;
}


.status-dot {
  width: 8px;
  height: 8px;

  flex-shrink: 0;

  background: #20df86;

  border-radius: 50%;

  box-shadow:
    0 0 8px #20df86;
}


.olt-ip {
  color: #7f8b93;

  font-size: 10px;
}


/* ============================= */
/* GRID DAS CPUs */
/* ============================= */

.cpu-grid {
  width: 100%;

  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 8px;

  box-sizing: border-box;

  font-family: Arial, sans-serif;
}


/* ============================= */
/* CARD CPU */
/* ============================= */

.cpu-card {
  min-width: 0;
  min-height: 64px;

  display: flex;
  align-items: center;

  gap: 8px;

  padding: 7px 8px;

  box-sizing: border-box;

  overflow: hidden;

  background:
    linear-gradient(
      135deg,
      rgba(18, 24, 29, 0.95),
      rgba(12, 16, 20, 0.95)
    );

  border: 1px solid rgba(50, 255, 160, 0.15);
  border-left: 4px solid #24d989;

  border-radius: 9px;

  box-shadow:
    0 0 12px rgba(36, 217, 137, 0.10),
    inset 0 0 12px rgba(255, 255, 255, 0.02);
}


/* ============================= */
/* GAUGE CPU */
/* ============================= */

.cpu-gauge {
  --value: 0;

  width: 46px;
  height: 46px;
  min-width: 46px;

  flex-shrink: 0;

  border-radius: 50%;

  position: relative;

  background:
    conic-gradient(
      #20df86 calc(var(--value) * 1%),
      #202a30 0
    );

  filter:
    drop-shadow(
      0 0 5px rgba(32, 223, 134, 0.45)
    );
}


.cpu-gauge-inner {
  position: absolute;

  inset: 5px;

  background: #11181d;

  border-radius: 50%;

  box-shadow:
    inset 0 0 8px rgba(0, 0, 0, 0.8);
}


/* ============================= */
/* INFORMAÇÕES CPU */
/* ============================= */

.cpu-info {
  display: flex;
  flex-direction: column;
  justify-content: center;

  min-width: 0;
}


.cpu-title {
  color: #dedede;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 0.4px;

  white-space: nowrap;
}


.cpu-value {
  margin-top: 4px;

  color: #21df88;

  font-size: 14px;
  font-weight: 700;

  white-space: nowrap;

  text-shadow:
    0 0 6px rgba(33, 223, 136, 0.50);
}


.rotation-unit {
  margin-top: 1px;

  color: #7f8b93;

  font-size: 9px;
  font-weight: 600;

  white-space: nowrap;
}

/* ============================= */
/* CPU GERAL */
/* ============================= */

.cpu-card-geral {
  background:
    linear-gradient(
      135deg,
      rgba(18, 38, 33, 0.98),
      rgba(8, 22, 18, 0.98)
    );

  border: 1px solid rgba(32, 223, 134, 0.45);
  border-left: 4px solid #20df86;

  box-shadow:
    0 0 18px rgba(32, 223, 134, 0.18),
    inset 0 0 16px rgba(32, 223, 134, 0.05);
}


.cpu-gauge-geral {
  filter:
    drop-shadow(
      0 0 8px rgba(32, 223, 134, 0.65)
    );
}


.cpu-title-geral {
  color: #ffffff;

  font-weight: 800;
}


.cpu-value-geral {
  color: #20df86;

  font-size: 15px;
  font-weight: 800;

  text-shadow:
    0 0 8px rgba(32, 223, 134, 0.65);
}


/* ============================= */
/* RESPONSIVO */
/* ============================= */

@media (max-width: 1000px) {

  .cpu-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


@media (max-width: 600px) {

  .olt-header {
    padding: 8px 10px;
  }


  .olt-icon {
    width: 40px;
    height: 40px;

    font-size: 10px;
  }


  .olt-name {
    font-size: 14px;
  }


  .olt-description {
    font-size: 9px;
  }


  .olt-status {
    font-size: 10px;
  }


  .olt-ip {
    font-size: 9px;
  }


  .cpu-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    gap: 6px;
  }


  .cpu-card {
    min-height: 58px;

    padding: 6px;
  }


  .cpu-gauge {
    width: 40px;
    height: 40px;
    min-width: 40px;
  }


  .cpu-title {
    font-size: 8px;
  }


  .cpu-value {
    font-size: 13px;
  }

}

